{
  "candidate_id": "candidate-1",
  "filepath": "lib/ldapauth.js",
  "changed_line": 135,
  "statement": "var searchFilter = self.opts.searchFilter.replace(/{{username}}/g, username);",
  "change_type": "A",
  "function_name": "_findUser",
  "operation_type": "string_transformation",
  "selection_reason": "observable input 'username' -> regex replacement operation -> constructs LDAP search filter that may be vulnerable to injection if not properly sanitized",
  "security_relevance_score": 0.7,
  "code_context": "1: /**
2:  * Copyright 2011 (c) Trent Mick.
3:  *
4:  * LDAP auth.
5:  *
6:  * Usage:
7:  *    var LdapAuth = require('ldapauth');
8:  *    var auth = new LdapAuth({url: 'ldaps://ldap.example.com:663', ...});
9:  *    ...
10:  *    auth.authenticate(username, password, function (err, user) { ... });
11:  *    ...
12:  *    auth.close(function (err) { ... })
13:  */
14: 
15: var assert = require('assert');
16: var bcrypt = require('bcrypt');
17: var ldap = require('ldapjs');
18: var debug = console.warn;
19: var format = require('util').format;
20: 
21: 
22: 
23: /**
24:  * Create an LDAP auth class. Primary usage is the `.authenticate` method.
25:  *
26:  * @param opts {Object} Config options. Keys (required, unless says
27:  *      otherwise) are:
28:  *    url {String} E.g. 'ldaps://ldap.example.com:663'
29:  *    adminDn {String} E.g. 'uid=myapp,ou=users,o=example.com'
30:  *    adminPassword {String} Password for adminDn.
31:  *    searchBase {String} The base DN from which to search for users by
32:  *        username. E.g. 'ou=users,o=example.com'
33:  *    searchFilter {String} LDAP search filter with which to find a user by
34:  *        username, e.g. '(uid={{username}})'. Use the literal '{{username}}'
35:  *        to have the given username be interpolated in for the LDAP
36:  *        search.
37:  *    log4js {Module} Optional. The require'd log4js module to use for logging.
38:  *        logging. If given this will result in TRACE-level logging for
39:  *        ldapauth.
40:  *    verbose {Boolean} Optional, default false. If `log4js` is also given,
41:  *        this will add TRACE-level logging for ldapjs (quite verbose).
42:  *    cache {Boolean} Optional, default false. If true, then up to 100
43:  *        credentials at a time will be cached for 5 minutes.
44:  *    timeout {Integer} Optional, default Infinity. How long the client should
45:  *        let operations live for before timing out.
46:  *    connectTimeout {Integer} Optional, default is up to the OS. How long the
47:  *        client should wait before timing out on TCP connections.
48:  *    tlsOptions {Object} Additional options passed to the TLS connection layer
49:  *        when connecting via ldaps://. See
50:  *        http://nodejs.org/api/tls.html#tls_tls_connect_options_callback
51:  *        for available options
52:  */
53: function LdapAuth(opts) {
54:   this.opts = opts;
55:   assert.ok(opts.url);
56:   assert.ok(opts.adminDn);
57:   assert.ok(opts.searchBase);
58:   assert.ok(opts.searchFilter);
59: 
60:   this.log = opts.log4js && opts.log4js.getLogger('ldapauth');
61: 
62:   if (opts.cache) {
63:     var Cache = require('./cache');
64:     this.userCache = new Cache(100, 300, this.log, 'user');
65:   }
66: 
67:   var clientOpts = {url: opts.url};
68:   if (opts.log4js && opts.verbose) {
69:     clientOpts.log4js = opts.log4js;
70:   }
71:   if (opts.timeout) {
72:     clientOpts.timeout = opts.timeout;
73:   }
74:   if (opts.connectTimeout) {
75:     clientOpts.connectTimeout = opts.connectTimeout;
76:   }
77:   if (opts.tlsOptions) {
78:     clientOpts.tlsOptions = opts.tlsOptions;
79:   }
80:   this._adminClient = ldap.createClient(clientOpts);
81:   this._adminBound = false;
82:   this._userClient = ldap.createClient(clientOpts);
83: 
84:   this._salt = bcrypt.genSaltSync();
85: }
86: 
87: 
88: LdapAuth.prototype.close = function (callback) {
89:   if (! this._adminBound) {
90:     callback()
91:   } else {
92:     this._adminClient.unbind(function (err) {
93:       callback(err);
94:     });
95:   }
96: }
97: 
98: 
99: /**
100:  * Ensure that `this._adminClient` is bound.
101:  */
102: LdapAuth.prototype._adminBind = function (callback) {
103:   if (this._adminBound) {
104:     return callback();
105:   }
106:   var self = this;
107:   this._adminClient.bind(this.opts.adminDn, this.opts.adminPassword,
108:                          function (err) {
109:     if (err) {
110:       self.log && self.log.trace('ldap authenticate: bind error: %s', err);
111:       return callback(err);
112:     }
113:     return callback();
114:   });
115: }
116: 
117: 
118: /**
119:  * Find the user record for the given username.
120:  *
121:  * @param username {String}
122:  * @param callback {Function} `function (err, user)`. If no such user is
123:  *    found but no error processing, then `user` is undefined.
124:  *
125:  */
126: LdapAuth.prototype._findUser = function (username, callback) {
127:   var self = this;
128:   if (!username) {
129:     return callback("empty username");
130:   }
131:   self._adminBind(function (err) {
132:     if (err)
133:       return callback(err);
134: 
135:     var searchFilter = self.opts.searchFilter.replace(/{{username}}/g, username);
136:     var opts = {filter: searchFilter, scope: 'sub'};
137:     self._adminClient.search(self.opts.searchBase, opts,
138:                              function (err, result) {
139:       if (err) {
140:         self.log && self.log.trace('ldap authenticate: search error: %s', err);
141:         return callback(err);
142:       }
143:       var items = [];
144:       result.on('searchEntry', function (entry) {
145:         items.push(entry.object);
146:       });
147:       result.on('error', function (err) {
148:         self.log && self.log.trace(
149:           'ldap authenticate: search error event: %s', err);
150:         return callback(err);
151:       });
152:       result.on('end', function (result) {
153:         if (result.status !== 0) {
154:           var err = 'non-zero status from LDAP search: ' + result.status;
155:           self.log && self.log.trace('ldap authenticate: %s', err);
156:           return callback(err);
157:         }
158:         switch (items.length) {
159:         case 0:
160:           return callback();
161:         case 1:
162:           return callback(null, items[0])
163:         default:
164:           return callback(format(
165:             'unexpected number of matches (%s) for "%s" username',
166:             items.length, username));
167:         }
168:       });
169:     });
170:   });
171: }
172: 
173: 
174: /**
175:  *
176:  */
177: LdapAuth.prototype.authenticate = function (username, password, callback) {
178:   var self = this;
179: 
180:   if (self.opts.cache) {
181:     // Check cache. 'cached' is `{password: <hashed-password>, user: <user>}`.
182:     var cached = self.userCache.get(username);
183:     if (cached && bcrypt.compareSync(password, cached.password)) {
184:       return callback(null, cached.user)
185:     }
186:   }
187: 
188:   // 1. Find the user DN in question.
189:   self._findUser(username, function (err, user) {
190:     if (err)
191:       return callback(err);
192:     if (!user)
193:       return callback(format('no such user: "%s"', username));
194:     // 2. Attempt to bind as that user to check password.
195:     self._userClient.bind(user.dn, password, function (err) {
196:       if (err) {
197:         self.log && self.log.trace('ldap authenticate: bind error: %s', err);
198:         return callback(err);
199:       }
200:       if (self.opts.cache) {
201:         bcrypt.hash(password, self._salt, function (err, hash) {
202:           self.userCache.set(username, {password: hash, user: user});
203:           return callback(null, user);
204:         });
205:       } else {
206:         return callback(null, user);
207:       }
208:     });
209:   });
210: }
211: 
212: 
213: 
214: module.exports = LdapAuth;",
  "source_summary": "The 'username' parameter comes from the function's input and is used to replace '{{username}}' in the searchFilter template defined by self.opts.searchFilter. The searchFilter is configured by the user via the LdapAuth constructor options.",
  "sink_summary": "The constructed searchFilter is passed as the 'filter' option to ldapjs client's search method, which will be executed against an LDAP server.",
  "guard_summary": "There are no explicit validation or sanitization of the username before it is substituted into the searchFilter. The only check is that username is not empty. The searchFilter template itself is user-provided and not validated for safety.",
  "risk_pattern": "The username parameter is directly interpolated into a user-defined LDAP search filter template without sanitization, which could allow an attacker to modify the LDAP query structure if the template allows it.",
  "used_variable_sources": [
    "username",
    "self.opts.searchFilter"
  ],
  "called_function_context": [
    "self._adminClient.search"
  ],
  "enclosing_conditions": [],
  "context_summary": "The _findUser function constructs an LDAP search filter by replacing '{{username}}' in a user-provided template with the input username. This constructed filter is then used in an LDAP search operation without additional validation or sanitization of the username.",
  "unresolved_facts": [
    "Whether the user-provided searchFilter template allows for structural modification that could lead to LDAP injection",
    "The exact format and content of self.opts.searchFilter as provided by the user"
  ]
}

